use baconconsole::{catalog::{Catalog, CatalogGame, InstallationInput, UserProfile}, disc::{load_manifest, manifest_total_bytes, BaconManifest}, emulators::{list_profiles, merge_profiles, profile_supports_platform, retroarch_arguments, save_profile, validate_profile, EmulatorKind, EmulatorProfile, Platform}, launcher::{steam_launch_request, GameLauncher, LaunchRequest, NativeProcessRunner}, library::{list_installs, register_install, LibraryRecord}, local_library::{has_supported_extension, scan_authorized_media}, metadata::{integration_status as metadata_integration_status, metadata_status, ArtworkCache, ArtworkKind, ArtworkRecord, IntegrationStatus, MetadataProvider, MetadataStatus, MetadataStore, RetroAchievementsProvider, SecretStore, SteamGridDbProvider, WindowsCredentialStore}, steam_library::discover_installed_games, storage::{available_space, copy_verified_with, verify_manifest_files, CopyOptions, CopyProgress}};

pub struct CopyJobs(pub Mutex<HashMap<String, Arc<AtomicBool>>>);
pub struct NativeLauncher(pub GameLauncher<NativeProcessRunner>);
fn catalog(app:&AppHandle)->Result<Catalog,String> { let root=app.path().app_data_dir().map_err(|error|error.to_string())?.join("library"); Catalog::open(&root) }
fn effective_emulator_profiles(app:&AppHandle)->Result<Vec<EmulatorProfile>,String>{ let root=app.path().app_data_dir().map_err(|error|error.to_string())?.join("emulators"); Ok(merge_profiles(bundled_emulator_profiles(),list_profiles(&root).map_err(|error|error.to_string())?)) }
fn metadata_store(app:&AppHandle)->Result<MetadataStore,String> { let root=app.path().app_data_dir().map_err(|error|error.to_string())?.join("library"); MetadataStore::open(&root) }
fn artwork_root(app:&AppHandle)->Result<PathBuf,String> { Ok(app.path().app_data_dir().map_err(|error|error.to_string())?) }
#[derive(Serialize)]
#[serde(rename_all = "camelCase")]
pub struct DiscSummary { pub id: String, pub title: String, pub platform: String, pub package_type: String, pub entry_point: String, pub modes: Vec<String>, pub file_count: usize, pub total_bytes: u64 }
impl TryFrom<(BaconManifest, PathBuf)> for DiscSummary { type Error = String; fn try_from((value, root): (BaconManifest, PathBuf)) -> Result<Self, Self::Error> { let total_bytes = manifest_total_bytes(&root).map_err(|error| error.to_string())?; Ok(Self { id:value.id, title:value.title, platform:value.platform, package_type:value.package_type, entry_point:value.entry_point, modes:value.modes, file_count:value.files.len(), total_bytes }) } }
#[derive(Serialize)]
#[serde(rename_all = "camelCase")]
pub struct StorageTarget { pub kind: String, pub root: String, pub available_bytes: u64 }
#[derive(Clone, Serialize)]
#[serde(rename_all = "camelCase")]
pub struct CopyProgressEvent { pub job_id: String, pub copied_bytes: u64, pub total_bytes: u64, pub completed_files: usize, pub file_count: usize }
impl CopyProgressEvent { fn from_progress(job_id: String, progress: CopyProgress) -> Self { Self { job_id, copied_bytes: progress.copied_bytes, total_bytes: progress.total_bytes, completed_files: progress.completed_files, file_count: progress.file_count } } }
#[derive(Serialize)]
#[serde(rename_all = "camelCase")]
pub struct LocalImportResult { pub imported: usize, pub titles: Vec<String> }
#[derive(Serialize)] #[serde(rename_all="camelCase")] pub struct SteamSyncResult { pub imported:usize, pub titles:Vec<String> }
#[derive(Serialize)] #[serde(rename_all="camelCase")] pub struct WindowsAppResult { pub title:String }

#[tauri::command] pub fn inspect_simulated_disc(root: String) -> Result<DiscSummary, String> { let root = PathBuf::from(root); load_manifest(&root).map_err(|error| error.to_string()).and_then(|manifest| DiscSummary::try_from((manifest, root))) }
#[tauri::command] pub fn verify_simulated_disc(root: String) -> Result<u64, String> { verify_manifest_files(&PathBuf::from(root)).map_err(|error| error.to_string()) }
#[tauri::command] pub fn copy_simulated_disc(root: String, destination: String) -> Result<u64, String> { baconconsole::storage::copy_verified(&PathBuf::from(root), &PathBuf::from(destination)).map_err(|error| error.to_string()) }
#[tauri::command] pub fn get_storage_targets(app: AppHandle) -> Result<Vec<StorageTarget>, String> { let root = app.path().app_data_dir().map_err(|error| error.to_string())?.join("storage"); std::fs::create_dir_all(&root).map_err(|error| error.to_string())?; let available_bytes = available_space(&root).map_err(|error| error.to_string())?; Ok(vec![StorageTarget { kind: "ssd".into(), root: root.to_string_lossy().to_string(), available_bytes }]) }
#[tauri::command] pub fn start_verified_copy(app: AppHandle, jobs: State<CopyJobs>, job_id: String, root: String, destination: String, target_kind: String) -> Result<u64, String> {
    let flag = Arc::new(AtomicBool::new(false)); jobs.0.lock().map_err(|_| "copy job state unavailable".to_string())?.insert(job_id.clone(), flag.clone());
    let destination_path = PathBuf::from(&destination); let available = available_space(&destination_path).map_err(|error| error.to_string())?;
    let result = copy_verified_with(&PathBuf::from(&root), &destination_path, CopyOptions::with_available_space_and_cancel(available, flag), |progress| { let _ = app.emit("bacondisc-copy-progress", CopyProgressEvent::from_progress(job_id.clone(), progress)); }).map_err(|error| error.to_string());
    jobs.0.lock().map_err(|_| "copy job state unavailable".to_string())?.remove(&job_id); let copied = result?;
    if target_kind == "permanent" { let manifest = load_manifest(&PathBuf::from(root)).map_err(|error| error.to_string())?; let library_root = app.path().app_data_dir().map_err(|error| error.to_string())?.join("library"); register_install(&library_root, LibraryRecord::permanent(manifest.id.clone(), manifest.title.clone(), destination.clone(), true)).map_err(|error| error.to_string())?; catalog(&app)?.upsert_installation(InstallationInput::new(format!("bacondisc:{}",manifest.id),manifest.title,manifest.platform,"ssd",destination,true))?; }
    Ok(copied)
}
#[tauri::command] pub fn cancel_copy(jobs: State<CopyJobs>, job_id: String) -> Result<(), String> { if let Some(flag) = jobs.0.lock().map_err(|_| "copy job state unavailable".to_string())?.get(&job_id) { flag.store(true, std::sync::atomic::Ordering::Relaxed); } Ok(()) }
#[tauri::command] pub fn list_library_records(app: AppHandle) -> Result<Vec<LibraryRecord>, String> { let library_root = app.path().app_data_dir().map_err(|error| error.to_string())?.join("library"); list_installs(&library_root).map_err(|error| error.to_string()) }
#[tauri::command] pub fn list_catalog_games(app:AppHandle)->Result<Vec<CatalogGame>,String>{ catalog(&app)?.list_games() }
fn default_steam_root()->Option<PathBuf>{["PROGRAMFILES(X86)","PROGRAMFILES"].into_iter().filter_map(|name|std::env::var_os(name)).map(PathBuf::from).map(|base|base.join("Steam")).find(|path|path.join("steamapps").is_dir())}
#[tauri::command] pub fn sync_steam_library(app:AppHandle,root:Option<String>)->Result<SteamSyncResult,String>{let root=match root.filter(|value|!value.trim().is_empty()){Some(value)=>PathBuf::from(value),None=>default_steam_root().ok_or("Não encontramos uma instalação Steam padrão. Selecione a pasta raiz da Steam uma vez para sincronizar.")?};let items=discover_installed_games(&root)?;let titles=items.iter().map(|item|item.title.clone()).collect();let imported=catalog(&app)?.upsert_steam_installs(&items)?;Ok(SteamSyncResult{imported,titles})}
#[tauri::command] pub fn register_windows_application(app:AppHandle,path:String)->Result<WindowsAppResult,String>{let executable=PathBuf::from(path).canonicalize().map_err(|_|"Executável não encontrado.")?;if !executable.is_file()||!executable.extension().and_then(|value|value.to_str()).is_some_and(|value|value.eq_ignore_ascii_case("exe")){return Err("Selecione um executável .exe válido.".into())}let title=executable.file_stem().and_then(|value|value.to_str()).filter(|value|!value.is_empty()).ok_or("Nome do executável inválido.")?.to_owned();let stable=executable.to_string_lossy().to_lowercase();catalog(&app)?.upsert_installation(InstallationInput::new(format!("windows:{stable}"),title.clone(),"windows","windows-app",executable.to_string_lossy(),false))?;Ok(WindowsAppResult{title})}
#[tauri::command] pub fn list_local_users(app:AppHandle)->Result<Vec<UserProfile>,String>{ catalog(&app)?.list_users() }
