#[tauri::command] pub fn create_local_user(app:AppHandle,name:String,avatar:Option<String>)->Result<UserProfile,String>{ let name=name.trim(); if name.is_empty() || name.len()>32 { return Err("nome de perfil inválido".into()) }; catalog(&app)?.create_user(name,avatar.as_deref()) }
#[tauri::command] pub fn set_active_local_user(app:AppHandle,user_id:i64)->Result<(),String>{ catalog(&app)?.set_active_user(user_id) }
#[tauri::command] pub fn toggle_catalog_favorite(app:AppHandle,game_id:i64)->Result<bool,String>{ let store=catalog(&app)?; let user=store.active_user()?; store.toggle_favorite(user.id,game_id)?; store.is_favorite(user.id,game_id) }
#[tauri::command] pub fn steamgriddb_status()->MetadataStatus { metadata_status(&WindowsCredentialStore) }
#[tauri::command] pub fn integration_status()->Vec<IntegrationStatus>{ metadata_integration_status(&WindowsCredentialStore) }
#[tauri::command] pub fn configure_and_test_steamgriddb(api_key:String)->Result<IntegrationStatus,String>{let key=api_key.trim();if key.len()<8{return Err("chave SteamGridDB inválida".into())};WindowsCredentialStore.write("steamgriddb-api-key",key)?;SteamGridDbProvider::new(key.into())?.connection_status()}
#[tauri::command] pub fn configure_and_test_retroachievements(username:String,api_key:String)->Result<IntegrationStatus,String>{let user=username.trim();let key=api_key.trim();let provider=RetroAchievementsProvider::new(user.into(),key.into())?;let status=provider.connection_status()?;if matches!(status.state,baconconsole::metadata::IntegrationState::Connected){WindowsCredentialStore.write("retroachievements-user",user)?;WindowsCredentialStore.write("retroachievements-api-key",key)?;}Ok(status)}
#[tauri::command] pub fn configure_steamgriddb(api_key:String)->Result<MetadataStatus,String>{ let key=api_key.trim(); if key.len()<8{return Err("chave SteamGridDB inválida".into())}; WindowsCredentialStore.write("steamgriddb-api-key",key)?; Ok(metadata_status(&WindowsCredentialStore)) }
#[tauri::command] pub fn search_steamgriddb(title:String)->Result<Vec<baconconsole::metadata::MetadataCandidate>,String>{ let key=WindowsCredentialStore.read("steamgriddb-api-key")?.ok_or("SteamGridDB não configurado")?; SteamGridDbProvider::new(key)?.search(&title) }
#[tauri::command] pub fn steamgriddb_artwork_options(remote_id:i64,kind:String)->Result<Vec<baconconsole::metadata::ArtworkOption>,String>{ let key=WindowsCredentialStore.read("steamgriddb-api-key")?.ok_or("SteamGridDB não configurado")?; SteamGridDbProvider::new(key)?.artwork_options(remote_id,ArtworkKind::from_str(&kind)?) }
#[tauri::command] pub fn cache_steamgriddb_artwork(app:AppHandle,game_id:i64,remote_id:i64,kind:String,url:String)->Result<ArtworkRecord,String>{ let key=WindowsCredentialStore.read("steamgriddb-api-key")?.ok_or("SteamGridDB não configurado")?; let kind=ArtworkKind::from_str(&kind)?; let cached=SteamGridDbProvider::new(key)?.fetch_artwork(&ArtworkCache::new(&artwork_root(&app)?)?,&url)?; let record=ArtworkRecord::new("steamgriddb",remote_id,kind,url,cached.local_path,cached.mime,cached.hash); metadata_store(&app)?.save_selected_artwork(game_id,&record)?; Ok(record) }
#[tauri::command] pub fn selected_game_artwork(app:AppHandle,game_id:i64)->Result<Vec<ArtworkRecord>,String>{ let base=artwork_root(&app)?; let mut records=metadata_store(&app)?.all_selected_artwork(game_id)?; for record in &mut records { record.local_path=base.join(&record.local_path).to_string_lossy().to_string(); } Ok(records) }
#[tauri::command] pub fn list_emulator_profiles(app: AppHandle) -> Result<Vec<EmulatorProfile>, String> { let root = app.path().app_data_dir().map_err(|error| error.to_string())?.join("emulators"); list_profiles(&root).map_err(|error| error.to_string()) }
#[tauri::command] pub fn list_effective_emulator_profiles(app: AppHandle) -> Result<Vec<EmulatorProfile>, String> { effective_emulator_profiles(&app) }
#[tauri::command] pub fn bundled_emulator_profiles() -> Vec<EmulatorProfile> { let base = std::env::var_os("LOCALAPPDATA").map(PathBuf::from).unwrap_or_default().join("BaconConsole").join("tools"); let retro_root = base.join("RetroArch").join("RetroArch-Win64"); let mut retroarch = EmulatorProfile::new("retroarch", "RetroArch", EmulatorKind::RetroArch, retro_root.join("retroarch.exe").to_string_lossy()); for (platform, core) in [(Platform::Nes, "fceumm_libretro.dll"), (Platform::Snes, "snes9x_libretro.dll"), (Platform::Megadrive, "genesis_plus_gx_libretro.dll"), (Platform::Gba, "mgba_libretro.dll")] { retroarch.cores.insert(platform, retro_root.join("cores").join(core).to_string_lossy().to_string()); } vec![retroarch, EmulatorProfile::new("duckstation", "DuckStation", EmulatorKind::Duckstation, base.join("DuckStation").join("duckstation-qt-x64-ReleaseLTCG.exe").to_string_lossy()), EmulatorProfile::new("pcsx2", "PCSX2", EmulatorKind::Pcsx2, base.join("PCSX2").join("pcsx2-qt.exe").to_string_lossy()), EmulatorProfile::new("windows-portable", "Windows portátil", EmulatorKind::WindowsPortable, "")].into_iter().filter(|profile| validate_profile(profile).is_ok()).collect() }
#[tauri::command] pub fn save_emulator_profile(app: AppHandle, profile: EmulatorProfile) -> Result<(), String> { validate_profile(&profile).map_err(|error| error.to_string())?; let root = app.path().app_data_dir().map_err(|error| error.to_string())?.join("emulators"); save_profile(&root, profile).map_err(|error| error.to_string()) }
#[tauri::command] pub fn import_authorized_library(app:AppHandle,root:String,platform:String,profile_id:String)->Result<LocalImportResult,String>{ let selected_platform=parse_platform(&platform)?; let profile=effective_emulator_profiles(&app)?.into_iter().find(|profile|profile.id==profile_id).ok_or("emulador selecionado não foi encontrado")?; validate_profile(&profile).map_err(|_|"emulador selecionado não está disponível".to_string())?; if !profile_supports_platform(&profile,selected_platform){return Err("o emulador selecionado não é compatível com esta plataforma".into())}; let media=scan_authorized_media(Path::new(&root),selected_platform)?; let titles=media.iter().map(|item|item.title.clone()).collect::<Vec<_>>(); let imported=catalog(&app)?.upsert_local_imports(&profile.id,&media)?; Ok(LocalImportResult{imported,titles}) }
fn parse_platform(value: &str) -> Result<Platform, String> { match value { "nes" => Ok(Platform::Nes), "snes" => Ok(Platform::Snes), "megadrive" => Ok(Platform::Megadrive), "gba" => Ok(Platform::Gba), "ps1" => Ok(Platform::Ps1), "ps2" => Ok(Platform::Ps2), "windows" => Ok(Platform::Windows), _ => Err("plataforma não suportada".into()) } }
fn validated_content(root: &str, relative: &str) -> Result<PathBuf, String> { let root = Path::new(root).canonicalize().map_err(|_| "raiz de conteúdo inválida".to_string())?; let relative = Path::new(relative); if relative.is_absolute() || relative.components().any(|component| matches!(component, std::path::Component::ParentDir | std::path::Component::Prefix(_) | std::path::Component::RootDir)) { return Err("caminho de conteúdo inseguro".into()); } let content = root.join(relative).canonicalize().map_err(|_| "conteúdo não encontrado".to_string())?; if !content.starts_with(&root) || !content.is_file() { return Err("conteúdo fora da raiz permitida".into()); } Ok(content) }
fn build_launch_request(profile:&EmulatorProfile,platform:Platform,content:&Path)->Result<LaunchRequest,String>{ if !profile_supports_platform(profile,platform){return Err("o emulador selecionado não é compatível com este jogo".into())}; if platform != Platform::Windows && !has_supported_extension(content,platform){return Err("formato de mídia não é compatível com a plataforma selecionada".into())}; match profile.kind { EmulatorKind::RetroArch=>Ok(LaunchRequest::new(&profile.executable,retroarch_arguments(profile,platform,content).map_err(|error|error.to_string())?.into_iter().map(|argument|argument.to_string_lossy().to_string()).collect())), EmulatorKind::Duckstation|EmulatorKind::Pcsx2=>Ok(LaunchRequest::new(&profile.executable,vec![content.to_string_lossy().to_string()])), EmulatorKind::WindowsPortable=>{if !content.extension().is_some_and(|extension|extension.eq_ignore_ascii_case("exe")){return Err("jogos portáteis devem apontar para um .exe".into())};Ok(LaunchRequest::new(content,Vec::new()))} } }
fn spawn_launch(app:AppHandle,launcher:GameLauncher<NativeProcessRunner>,request:LaunchRequest,session:Option<i64>,library_root:PathBuf){std::thread::spawn(move||{let started=std::time::Instant::now();let _=app.emit("baconconsole-launch-state","running");let result=launcher.launch(request);if let Some(session_id)=session{let _=Catalog::open(&library_root).and_then(|store|store.finish_play_session(session_id,started.elapsed().as_secs()as i64));}let _=app.emit("baconconsole-launch-state",if result.is_ok(){"returned"}else{"failed"});});}
#[tauri::command] pub fn launch_game(app: AppHandle, launcher: State<NativeLauncher>, profile_id: String, content_root: String, content_relative: String, content_platform: String) -> Result<(), String> { let profile=effective_emulator_profiles(&app)?.into_iter().find(|profile|profile.id==profile_id).ok_or("perfil de emulador não encontrado")?; validate_profile(&profile).map_err(|error|error.to_string())?; let content=validated_content(&content_root,&content_relative)?; let selected_platform=parse_platform(&content_platform)?; let request=build_launch_request(&profile,selected_platform,&content)?; let store=catalog(&app)?; let identity=format!("portable:{}",content.to_string_lossy().to_lowercase()); let title=content.file_stem().and_then(|value|value.to_str()).unwrap_or("Conteúdo local").to_owned(); store.upsert_installation(InstallationInput::new(identity.clone(),title,content_platform, "local",content.to_string_lossy(),false))?; let user=store.active_user()?;let session=store.game_id_for_identity(&identity)?.and_then(|game|store.start_play_session(user.id,game).ok());let library_root=app.path().app_data_dir().map_err(|error|error.to_string())?.join("library");spawn_launch(app,launcher.0.clone(),request,session,library_root);Ok(()) }
#[tauri::command] pub fn launch_catalog_game(app:AppHandle,launcher:State<NativeLauncher>,game_id:i64,installation_id:i64)->Result<(),String>{let store=catalog(&app)?;if let Some(install)=store.launchable_steam(game_id,installation_id)?{let request=steam_launch_request(&install.install_path)?;let user=store.active_user()?;let session=store.start_play_session(user.id,game_id).ok();let root=app.path().app_data_dir().map_err(|e|e.to_string())?.join("library");spawn_launch(app,launcher.0.clone(),request,session,root);return Ok(())};if let Some(install)=store.launchable_windows_application(game_id,installation_id)?{let request=LaunchRequest::new(install.install_path,Vec::new());let user=store.active_user()?;let session=store.start_play_session(user.id,game_id).ok();let root=app.path().app_data_dir().map_err(|e|e.to_string())?.join("library");spawn_launch(app,launcher.0.clone(),request,session,root);return Ok(())};let installation=store.launchable_local_import(game_id,installation_id)?.ok_or("jogo local indisponível")?;let profile_id=installation.emulator_profile_id.ok_or("jogo não possui emulador associado")?;let profile=effective_emulator_profiles(&app)?.into_iter().find(|profile|profile.id==profile_id).ok_or("emulador associado não foi encontrado")?;validate_profile(&profile).map_err(|_|"emulador associado não está disponível".to_string())?;let content_path=PathBuf::from(&installation.install_path);let root=content_path.parent().ok_or("caminho do jogo inválido")?;let filename=content_path.file_name().and_then(|value|value.to_str()).ok_or("caminho do jogo inválido")?;let content=validated_content(&root.to_string_lossy(),filename)?;let selected_platform=parse_platform(&installation.platform)?;let request=build_launch_request(&profile,selected_platform,&content)?;let user=store.active_user()?;let session=store.start_play_session(user.id,game_id).ok();let library_root=app.path().app_data_dir().map_err(|error|error.to_string())?.join("library");spawn_launch(app,launcher.0.clone(),request,session,library_root);Ok(())}
#[tauri::command] pub fn launch_steam_game(app:AppHandle,launcher:State<NativeLauncher>,game_id:i64,installation_id:i64)->Result<(),String>{let store=catalog(&app)?;let install=store.launchable_steam(game_id,installation_id)?.ok_or("jogo Steam indisponível")?;let request=steam_launch_request(&install.install_path)?;let user=store.active_user()?;let session=store.start_play_session(user.id,game_id).ok();let root=app.path().app_data_dir().map_err(|e|e.to_string())?.join("library");spawn_launch(app,launcher.0.clone(),request,session,root);Ok(())}
